def is_integer(x): return x == math_floor(x) a_pythagorean_triple_between(5, 15)
a_pythagorean_triple_between_2 a_pythagorean_triple_between_2_example
(define (a-pythagorean-triple-between low high) (let ((i (an-integer-between low high)) (hsq (* high high))) (let ((j (an-integer-between i high))) (let ((ksq (+ (* i i) (* j j)))) (require (>= hsq ksq)) (let ((k (sqrt ksq))) (require (integer? k)) (list i j k))))))
def a_pythagorean_triple_between(low, high): i = an_integer_between(low, high) hsq = high * high j = an_integer_between(i, high) ksq = i * i + j * j require(hsq >= ksq) k = math_sqrt(ksq) require(is_integer(k)) return llist(i, j, k)
